-- MM2 Trade Counter Bot - Matcha Loader
-- Standalone version for direct paste into Matcha executor
-- Press Numpad 8 to toggle bot on/off

local Players = game:GetService(\"Players\")\nlocal UserInputService = game:GetService(\"UserInputService\")\n\nlocal botRunning = false\nlocal tradeStartTime = nil\n\n-- Configuration\nlocal Config = {\n\tautoDeclineAfter = 120,\n\tcounterCapPercent = 97,\n\ttoggleKey = Enum.KeyCode.Keypad8,\n}\n\n-- Normalize text for comparison\nlocal function normalizeKey(str)\n\tif type(str) ~= \"string\" then\n\t\treturn \"\"\n\tend\n\tstr = str:lower()\n\tstr = str:gsub(\"'\", \"\")\n\tstr = str:gsub(\"%p\", \"\")\n\tstr = str:gsub(\"%s+\", \" \")\n\tstr = str:gsub(\"^%s+\", \"\")\n\tstr = str:gsub(\"%s+$\", \"\")\n\treturn str\nend\n\n-- Item Pricing Tables (from supremevalues.com)\nlocal godlyPrices = {\n\t[\"Traveler's Gun\"] = 5200,\n\t[\"Evergun\"] = 3450,\n\t[\"Evergreen\"] = 2625,\n\t[\"Constellation\"] = 2600,\n\t[\"Alienbeam\"] = 1950,\n\t[\"Turkey\"] = 1950,\n\t[\"Vampire's Gun\"] = 1900,\n\t[\"Darkshot\"] = 1800,\n\t[\"Raygun\"] = 1800,\n\t[\"Darksword\"] = 1775,\n\t[\"Blossom\"] = 1360,\n\t[\"Sakura\"] = 1350,\n\t[\"Sunrise\"] = 1075,\n\t[\"Bauble\"] = 675,\n\t[\"Snowcannon\"] = 675,\n\t[\"Soul\"] = 670,\n\t[\"Spirit\"] = 660,\n\t[\"Sunset\"] = 650,\n\t[\"Rainbow Gun\"] = 420,\n\t[\"Flora\"] = 410,\n\t[\"Rainbow\"] = 410,\n\t[\"Xenoknife\"] = 405,\n\t[\"Xenoshot\"] = 405,\n\t[\"Bloom\"] = 400,\n\t[\"Heart Wand\"] = 340,\n\t[\"Blizzard\"] = 305,\n\t[\"Snowstorm\"] = 305,\n\t[\"Ocean\"] = 275,\n\t[\"Waves\"] = 270,\n\t[\"Flowerwood Gun\"] = 250,\n\t[\"Flowerwood\"] = 245,\n\t[\"Snow Dagger\"] = 175,\n\t[\"Watergun\"] = 160,\n\t[\"Icecream\"] = 155,\n\t[\"Treat\"] = 155,\n\t[\"Sweet\"] = 150,\n\t[\"Borealis\"] = 145,\n\t[\"Australis\"] = 140,\n\t[\"Bat\"] = 125,\n\t[\"Beachy\"] = 90,\n\t[\"Sands\"] = 90,\n\t[\"Pearlshine\"] = 80,\n\t[\"Candy\"] = 80,\n\t[\"Pearl\"] = 75,\n\t[\"Ornament\"] = 70,\n\t[\"Heartblade\"] = 65,\n\t[\"Phantom\"] = 35,\n\t[\"Red Luger\"] = 35,\n\t[\"Spectre\"] = 35,\n\t[\"Candleflame\"] = 33,\n\t[\"Darkbringer\"] = 33,\n\t[\"Elderwood Blade\"] = 33,\n\t[\"Elderwood Revolver\"] = 33,\n\t[\"Iceblaster\"] = 33,\n\t[\"Makeshift\"] = 33,\n\t[\"Lightbringer\"] = 32,\n\t[\"Sugar\"] = 32,\n\t[\"Green Luger\"] = 23,\n\t[\"Amerilaser\"] = 22,\n\t[\"Laser\"] = 22,\n\t[\"Hallowgun\"] = 20,\n\t[\"Nightblade\"] = 20,\n\t[\"Shark\"] = 20,\n\t[\"Icebeam\"] = 18,\n\t[\"Luger\"] = 18,\n\t[\"Plasmabeam\"] = 18,\n\t[\"Swirly Gun\"] = 18,\n\t[\"Battleaxe II\"] = 17,\n\t[\"Blaster\"] = 17,\n\t[\"Ginger Luger\"] = 17,\n\t[\"Pixel\"] = 17,\n\t[\"Gemstone\"] = 15,\n\t[\"Iceflake\"] = 15,\n\t[\"Old Glory\"] = 15,\n\t[\"Plasmablade\"] = 15,\n\t[\"Slasher\"] = 15,\n\t[\"Vampire's Edge\"] = 15,\n\t[\"Cookiecane\"] = 13,\n\t[\"Deathshard\"] = 13,\n\t[\"Eternalcane\"] = 13,\n\t[\"Gingerblade\"] = 13,\n\t[\"Jinglegun\"] = 13,\n\t[\"Lugercane\"] = 13,\n\t[\"Minty\"] = 13,\n\t[\"Nebula\"] = 13,\n\t[\"Virtual\"] = 13,\n\t[\"Battleaxe\"] = 12,\n\t[\"Gingermint\"] = 12,\n\t[\"Swirly Blade\"] = 12,\n\t[\"Chill\"] = 10,\n\t[\"Clockwork\"] = 10,\n\t[\"Fang\"] = 10,\n\t[\"Frostsaber\"] = 10,\n\t[\"Heat\"] = 10,\n\t[\"Spider\"] = 10,\n\t[\"Tides\"] = 10,\n\t[\"Bioblade\"] = 8,\n\t[\"Eternal III\"] = 8,\n\t[\"Eternal IV\"] = 8,\n\t[\"Hallow's Blade\"] = 8,\n\t[\"Hallow's Edge\"] = 8,\n\t[\"Handsaw\"] = 8,\n\t[\"Boneblade\"] = 7,\n\t[\"Eternal\"] = 7,\n\t[\"Eternal II\"] = 7,\n\t[\"Frostbite\"] = 7,\n\t[\"Ghostblade\"] = 7,\n\t[\"Ice Dragon\"] = 7,\n\t[\"Ice Shard\"] = 7,\n\t[\"Prismatic\"] = 7,\n\t[\"Pumpking\"] = 7,\n\t[\"Saw\"] = 7,\n\t[\"Xmas\"] = 7,\n\t[\"Eggblade\"] = 5,\n\t[\"Flames\"] = 5,\n\t[\"Snowflake\"] = 5,\n\t[\"Winter's Edge\"] = 5,\n\t[\"Peppermint\"] = 4,\n\t[\"Cookieblade\"] = 3,\n\t[\"Blue Seer\"] = 3,\n\t[\"Purple Seer\"] = 3,\n\t[\"Red Seer\"] = 3,\n\t[\"Seer\"] = 3,\n\t[\"Orange Seer\"] = 2,\n\t[\"Yellow Seer\"] = 2,\n}\n\nlocal chromaPrices = {\n\t[\"C. Traveler's Gun\"] = 145000,\n\t[\"Chroma Evergun\"] = 56000,\n\t[\"Chroma Evergreen\"] = 42000,\n\t[\"Chroma Bauble\"] = 31000,\n\t[\"C. Constellation\"] = 29000,\n\t[\"C. Vampire's Gun\"] = 29000,\n\t[\"Chroma Alienbeam\"] = 24000,\n\t[\"Chroma Raygun\"] = 14250,\n\t[\"Chroma Sunrise\"] = 10750,\n\t[\"Chroma Snowcannon\"] = 7750,\n\t[\"Chroma Sunset\"] = 7750,\n\t[\"Chroma Blizzard\"] = 5500,\n\t[\"Chroma Snowstorm\"] = 4250,\n\t[\"Chroma Heart Wand\"] = 4000,\n\t[\"Chroma Watergun\"] = 2350,\n\t[\"Chroma Snow Dagger\"] = 2350,\n\t[\"Chroma Ornament\"] = 1825,\n\t[\"Chroma Treat\"] = 1775,\n\t[\"Chroma Icecream\"] = 1750,\n\t[\"Chroma Sweet\"] = 1725,\n\t[\"Chroma Sands\"] = 1200,\n\t[\"Chroma Beachy\"] = 1150,\n\t[\"Chroma Darkbringer\"] = 65,\n\t[\"Chroma Lightbringer\"] = 60,\n\t[\"Chroma Luger\"] = 50,\n\t[\"Chroma Candleflame\"] = 40,\n\t[\"Chroma Laser\"] = 40,\n\t[\"C. Elderwood Blade\"] = 37,\n\t[\"Chroma Deathshard\"] = 35,\n\t[\"Chroma Swirly Gun\"] = 35,\n\t[\"Chroma Cookiecane\"] = 32,\n\t[\"Chroma Fang\"] = 32,\n\t[\"Chroma Gemstone\"] = 32,\n\t[\"Chroma Shark\"] = 32,\n\t[\"Chroma Slasher\"] = 32,\n\t[\"Chroma Heat\"] = 28,\n\t[\"Chroma Seer\"] = 28,\n\t[\"Chroma Gingerblade\"] = 27,\n\t[\"Chroma Tides\"] = 27,\n\t[\"Chroma Saw\"] = 23,\n\t[\"Chroma Boneblade\"] = 22,\n}\n\nlocal ancientPrices = {\n\t[\"Gingerscope\"] = 15750,\n\t[\"Traveler's Axe\"] = 8000,\n\t[\"Celestial\"] = 2250,\n\t[\"Vampire's Axe\"] = 1600,\n\t[\"Harvester\"] = 250,\n\t[\"Icepiercer\"] = 160,\n\t[\"Icebreaker\"] = 65,\n\t[\"Batwing\"] = 42,\n\t[\"Elderwood Scythe\"] = 38,\n\t[\"Swirly Axe\"] = 38,\n\t[\"Hallowscythe\"] = 30,\n\t[\"Logchopper\"] = 18,\n\t[\"Icewing\"] = 13,\n}\n\nlocal uniquePrices = {\n\t[\"Corrupt\"] = 350,\n}\n\n-- Merge all prices\nlocal ITEM_PRICES = {}\nfor name, price in pairs(godlyPrices) do ITEM_PRICES[normalizeKey(name)] = price end\nfor name, price in pairs(chromaPrices) do ITEM_PRICES[normalizeKey(name)] = price end\nfor name, price in pairs(ancientPrices) do ITEM_PRICES[normalizeKey(name)] = price end\nfor name, price in pairs(uniquePrices) do ITEM_PRICES[normalizeKey(name)] = price end\n\n-- Blacklist (items that count as 0 value)\nlocal BLACKLIST = {\n\t[normalizeKey(\"Chroma Beachy\")] = true,\n\t[normalizeKey(\"Chroma Sands\")] = true,\n\t[normalizeKey(\"Chroma Heart Wand\")] = true,\n\t[normalizeKey(\"Flowerwood\")] = true,\n\t[normalizeKey(\"Flowerwood Gun\")] = true,\n\t[normalizeKey(\"Ornament\")] = true,\n}\n\n-- UI Detection Functions\nlocal function isTradeOpen()\n\tlocal gui = Players.LocalPlayer:FindFirstChild(\"PlayerGui\")\n\tif not gui then return false end\n\t\n\tfor _, obj in ipairs(gui:GetDescendants()) do\n\t\tif obj:IsA(\"TextLabel\") or obj:IsA(\"TextButton\") then\n\t\t\tlocal txt = normalizeKey(tostring(obj.Text or \"\"))\n\t\t\tif txt:find(\"trade\") or txt:find(\"offer\") or txt:find(\"accept\") or txt:find(\"decline\") then\n\t\t\t\treturn true\n\t\t\tend\n\t\tend\n\tend\n\treturn false\nend\n\nlocal function findTradeGui()\n\tlocal gui = Players.LocalPlayer:FindFirstChild(\"PlayerGui\")\n\tif not gui then return nil end\n\t\n\tfor _, obj in ipairs(gui:GetDescendants()) do\n\t\tif obj:IsA(\"Frame\") or obj:IsA(\"ScreenGui\") then\n\t\t\tlocal name = normalizeKey(obj.Name)\n\t\t\tif name:find(\"trade\") or name:find(\"offer\") then\n\t\t\t\treturn obj\n\t\t\tend\n\t\tend\n\tend\n\treturn nil\nend\n\nlocal function getVisibleTextLabels(container)\n\tlocal labels = {}\n\tif not container then return labels end\n\t\n\tfor _, obj in ipairs(container:GetDescendants()) do\n\t\tif obj:IsA(\"TextLabel\") or obj:IsA(\"TextButton\") then\n\t\t\tlocal text = tostring(obj.Text or \"\")\n\t\t\tif text ~= \"\" then\n\t\t\t\ttable.insert(labels, text)\n\t\t\tend\n\t\tend\n\tend\n\treturn labels\nend\n\nlocal function scanTradeForItems()\n\tlocal tradeGui = findTradeGui()\n\tif not tradeGui then return {} end\n\t\n\tlocal found = {}\n\tlocal seen = {}\n\tfor _, text in ipairs(getVisibleTextLabels(tradeGui)) do\n\t\tlocal normalized = normalizeKey(text)\n\t\tif ITEM_PRICES[normalized] then\n\t\t\tif not seen[normalized] then\n\t\t\t\tseen[normalized] = true\n\t\t\t\ttable.insert(found, { name = text, value = ITEM_PRICES[normalized], hasPrice = true })\n\t\t\tend\n\t\telse\n\t\t\tlocal trimmed = tostring(text):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n\t\t\tif trimmed ~= \"\" then\n\t\t\t\tlocal key = normalizeKey(trimmed)\n\t\t\t\tif not seen[key] then\n\t\t\t\t\tseen[key] = true\n\t\t\t\t\ttable.insert(found, { name = trimmed, value = 0, hasPrice = false })\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\treturn found\nend\n\nlocal function filterBlacklist(itemList)\n\tlocal filtered = {}\n\tlocal blacklistedItems = {}\n\t\n\tfor _, item in ipairs(itemList) do\n\t\tlocal key = normalizeKey(item.name)\n\t\tif BLACKLIST[key] then\n\t\t\ttable.insert(blacklistedItems, item.name)\n\t\telse\n\t\t\ttable.insert(filtered, item)\n\t\tend\n\tend\n\treturn filtered, blacklistedItems\nend\n\nlocal function calculateOffer(itemList)\n\tlocal total = 0\n\tfor _, item in ipairs(itemList) do\n\t\ttotal = total + item.value\n\tend\n\t\n\tif total <= 0 then return 0 end\n\tlocal target = total * (Config.counterCapPercent / 100)\n\treturn math.floor(target)\nend\n\nlocal function doubleCheckOffer(theirTotal, yourCounter)\n\tif yourCounter <= 0 then return false end\n\t\n\tlocal maxAllowed = math.floor(theirTotal * (Config.counterCapPercent / 100))\n\tif yourCounter > maxAllowed then\n\t\tprint(\"[MM2 Bot] Safety check failed: counter exceeds 97% of their offer.\")\n\t\treturn false\n\tend\n\t\n\tprint(\"[MM2 Bot] Safety check passed: offer is within 97% cap.\")\n\treturn true\nend\n\nlocal function findButtonByText(buttonName)\n\tlocal gui = Players.LocalPlayer:FindFirstChild(\"PlayerGui\")\n\tif not gui then return false end\n\t\n\tfor _, obj in ipairs(gui:GetDescendants()) do\n\t\tif obj:IsA(\"TextButton\") then\n\t\t\tlocal txt = normalizeKey(tostring(obj.Text or \"\"))\n\t\t\tlocal name = normalizeKey(tostring(obj.Name or \"\"))\n\t\t\tif txt:find(buttonName) or name:find(buttonName) then\n\t\t\t\tpcall(function()\n\t\t\t\t\tobj:Click()\n\t\t\t\t\tprint(\"[MM2 Bot] Clicked button: \" .. buttonName)\n\t\t\t\tend)\n\t\t\t\treturn true\n\t\t\tend\n\t\tend\n\tend\n\treturn false\nend\n\nlocal function findOfferInputField()\n\tlocal gui = Players.LocalPlayer:FindFirstChild(\"PlayerGui\")\n\tif not gui then return nil end\n\t\n\tfor _, obj in ipairs(gui:GetDescendants()) do\n\t\tif obj:IsA(\"TextBox\") then\n\t\t\treturn obj\n\t\tend\n\tend\n\treturn nil\nend\n\nlocal function submitCounter(amount)\n\tlocal inputField = findOfferInputField()\n\tif inputField then\n\t\tpcall(function()\n\t\t\tinputField:CaptureFocus()\n\t\t\tinputField.Text = tostring(amount)\n\t\t\tprint(\"[MM2 Bot] Counter offer submitted: \" .. amount)\n\t\tend)\n\t\treturn true\n\tend\n\treturn false\nend\n\nlocal function theyAcceptedCounter()\n\tlocal gui = Players.LocalPlayer:FindFirstChild(\"PlayerGui\")\n\tif not gui then return false end\n\t\n\tfor _, obj in ipairs(gui:GetDescendants()) do\n\t\tif obj:IsA(\"TextLabel\") then\n\t\t\tlocal txt = normalizeKey(tostring(obj.Text or \"\"))\n\t\t\tif txt:find(\"accepted\") or txt:find(\"waiting\") then\n\t\t\t\treturn true\n\t\t\tend\n\t\tend\n\tend\n\treturn false\nend\n\n-- Main Trade Processing\nlocal function processTrade()\n\tif not isTradeOpen() then\n\t\ttradeStartTime = nil\n\t\treturn\n\tend\n\t\n\tif tradeStartTime == nil then\n\t\ttradeStartTime = tick()\n\t\tprint(\"[MM2 Bot] Trade opened. Auto-decline in 2 minutes if no action is taken.\")\n\tend\n\t\n\tif (tick() - tradeStartTime) > Config.autoDeclineAfter then\n\t\tprint(\"[MM2 Bot] Trade has lasted over 2 minutes. Auto-declining trade.\")\n\t\tfindButtonByText(\"decline\")\n\t\ttradeStartTime = nil\n\t\treturn\n\tend\n\t\n\tlocal theirItems = scanTradeForItems()\n\tif #theirItems == 0 then\n\t\tprint(\"[MM2 Bot] No trade items detected yet.\")\n\t\treturn\n\tend\n\t\n\tlocal validItems, blacklistedItems = filterBlacklist(theirItems)\n\tif #blacklistedItems > 0 then\n\t\tprint(\"[MM2 Bot] Blacklisted items found (counted as 0 value):\")\n\t\tfor _, name in ipairs(blacklistedItems) do\n\t\t\tprint(\"  - \" .. name .. \" (ignored)\")\n\t\tend\n\tend\n\t\n\tlocal theirTotal = 0\n\tfor _, item in ipairs(validItems) do\n\t\ttheirTotal = theirTotal + item.value\n\tend\n\t\n\tif theirTotal <= 0 then\n\t\tprint(\"[MM2 Bot] Remaining offer value is 0. No counter offer will be made.\")\n\t\treturn\n\tend\n\t\n\tprint(\"[MM2 Bot] Valid offer items:\")\n\tfor _, item in ipairs(validItems) do\n\t\tprint(\"  - \" .. item.name .. \" = \" .. item.value)\n\tend\n\tprint(\"[MM2 Bot] Total valid value: \" .. theirTotal)\n\t\n\tlocal counterOffer = calculateOffer(validItems)\n\tprint(\"[MM2 Bot] Counter offer at 97%: \" .. counterOffer)\n\t\n\tif not doubleCheckOffer(theirTotal, counterOffer) then\n\t\tprint(\"[MM2 Bot] Not safe. Won't counter; waiting for manual review.\")\n\t\treturn\n\tend\n\t\n\tsubmitCounter(counterOffer)\n\twait(0.4)\n\tfindButtonByText(\"offer\")\n\tprint(\"[MM2 Bot] Counter submitted. Waiting for them to accept...\")\n\t\n\tlocal timeout = 60\n\tlocal elapsed = 0\n\twhile elapsed < timeout do\n\t\tif theyAcceptedCounter() then\n\t\t\tprint(\"[MM2 Bot] They accepted the counter. Auto-accepting now.\")\n\t\t\twait(0.5)\n\t\t\tfindButtonByText(\"accept\")\n\t\t\ttradeStartTime = nil\n\t\t\treturn\n\t\tend\n\t\tif (tick() - tradeStartTime) > Config.autoDeclineAfter then\n\t\t\tprint(\"[MM2 Bot] Trade exceeded 2 minutes while waiting for acceptance. Declining.\")\n\t\t\tfindButtonByText(\"decline\")\n\t\t\ttradeStartTime = nil\n\t\t\treturn\n\t\tend\n\t\telapsed = elapsed + 1\n\t\twait(1)\n\tend\n\t\n\tprint(\"[MM2 Bot] Timeout waiting for them to accept the counter.\")\n\ttradeStartTime = nil\nend\n\nlocal function startBot()\n\tbotRunning = true\n\tprint(\"[MM2 Bot] Started. Press Numpad 8 to stop.\")\n\tprint(\"[MM2 Bot] Flow: They send trade -> ignore blacklisted & unknown items as 0 -> counter at 97% -> decline after 2 minutes -> auto-accept on acceptance.\")\n\t\n\twhile botRunning do\n\t\tif isTradeOpen() then\n\t\t\tprocessTrade()\n\t\t\twait(1.5)\n\t\telse\n\t\t\ttradeStartTime = nil\n\t\t\twait(0.4)\n\t\tend\n\tend\n\t\n\tprint(\"[MM2 Bot] Stopped.\")\nend\n\n-- Toggle with Numpad 8\nUserInputService.InputBegan:Connect(function(input, gameProcessed)\n\tif gameProcessed then return end\n\t\n\tif input.KeyCode == Config.toggleKey then\n\t\tif botRunning then\n\t\t\tbotRunning = false\n\t\t\tprint(\"[MM2 Bot] Stopping bot...\")\n\t\telse\n\t\t\ttask.spawn(function()\n\t\t\t\tstartBot()\n\t\t\tend)\n\t\tend\n\tend\nend)\n\nprint(\"[MM2 Bot] Ready. Press Numpad 8 to toggle on.\")\n